import{az as a,P as t,Q as n,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const f=JSON.parse('{"title":"Render 与 Commit","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/双阶段.md","filePath":"框架/react/react/双阶段.md","lastUpdated":1785246304000}'),i={name:"框架/react/react/双阶段.md"};function s(l,e,o,d,p,c){return t(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="render-与-commit" tabindex="-1">Render 与 Commit <a class="header-anchor" href="#render-与-commit" aria-label="Permalink to “Render 与 Commit”">​</a></h1><p>React 把一次更新拆成两个阶段：<strong>Render（协调）</strong> 和 <strong>Commit（提交）</strong>。</p><p>拆开的原因：前面可以算、可以停、可以丢；后面改 DOM 和跑布局相关副作用时必须连贯，避免用户看到半成品 UI。</p><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to “总览”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>触发更新（setState / props ...）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   Render 阶段          ← 可打断（并发模式下）</span></span>
<span class="line"><span>  （Diff / 打标记）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   Commit 阶段          ← 同步、不可打断</span></span>
<span class="line"><span>  （改 DOM / 跑被动效果）</span></span></code></pre></div><h2 id="render-阶段" tabindex="-1">Render 阶段 <a class="header-anchor" href="#render-阶段" aria-label="Permalink to “Render 阶段”">​</a></h2><p>职责：算出「要改什么」，<strong>不直接操作 DOM</strong>。</p><p>典型工作：</p><ul><li>从根或脏子树开始遍历 Fiber</li><li>执行函数组件 / 类组件的 render，得到新的子元素</li><li>做 <a href="./协调">协调 Diff</a>，复用或创建 Fiber</li><li>给节点打上 Placement / Update / Deletion 等标记</li></ul><p>特点：</p><ul><li>在并发模式下可被更高优先级任务打断</li><li>被打断或过期后，可以丢弃当前 workInProgress，重新开始</li><li>此时屏幕上仍是上一棵 current 树</li></ul><h2 id="commit-阶段" tabindex="-1">Commit 阶段 <a class="header-anchor" href="#commit-阶段" aria-label="Permalink to “Commit 阶段”">​</a></h2><p>职责：把 Render 的结果<strong>一次性落到真实环境</strong>。</p><p>通常还细分为几类工作（理解即可）：</p><ol><li><strong>Before Mutation</strong>：改 DOM 前（如读布局、<code>getSnapshotBeforeUpdate</code>）</li><li><strong>Mutation</strong>：增删改 DOM</li><li><strong>Layout</strong>：DOM 已更新，同步跑 <code>useLayoutEffect</code> / <code>componentDidMount</code> 等</li><li>之后异步调度 <code>useEffect</code> 等被动效果</li></ol><p>特点：</p><ul><li><strong>同步完成</strong>，保证 UI 与内部状态一致</li><li>一般不可打断；中途停下容易露出中间态</li></ul><h2 id="副作用该写在哪" tabindex="-1">副作用该写在哪 <a class="header-anchor" href="#副作用该写在哪" aria-label="Permalink to “副作用该写在哪”">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>时机直觉</th></tr></thead><tbody><tr><td><code>useLayoutEffect</code></td><td>Commit 里、浏览器绘制前，适合量 DOM、同步改样式</td></tr><tr><td><code>useEffect</code></td><td>绘制后异步执行，适合请求、订阅、非阻塞逻辑</td></tr><tr><td>渲染期间</td><td>应保持纯净，不要在 render 里改 DOM 或发请求</td></tr></tbody></table><h2 id="和并发渲染的关系" tabindex="-1">和并发渲染的关系 <a class="header-anchor" href="#和并发渲染的关系" aria-label="Permalink to “和并发渲染的关系”">​</a></h2><ul><li><a href="./fiber">Fiber</a> 让 Render 阶段能按单元推进</li><li><a href="./并发渲染">并发渲染</a> 决定哪些更新更紧急、哪些可以延后</li><li>Commit 仍然强调「提交要完整」，避免撕裂</li></ul><p>所以：<strong>可中断的是算差异，不是改 DOM 的那一下。</strong></p><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>Render 像起草修改清单；Commit 像按清单施工。清单可以重写，施工最好一口气做完。</p>`,24)])])}const b=a(i,[["render",s]]);export{f as __pageData,b as default};
